# ── Build flat records ────────────────────────────────────────────────────────
now = datetime.utcnow().isoformat()
records = []

for place, days in DATA.items():
    for day_entry in days:
        m = MONTH_MAP[day_entry['month']]
        date_str = f"{day_entry['year']}-{m:02d}-{day_entry['day']:02d}"
        for batch in day_entry['batches']:
            code = batch['code']
            records.append({
                'place':       place,
                'date':        date_str,
                'serial':      batch['serial'],
                'code':        code,
                'packageName': PKG.get(code, code),
                'pax':         batch['pax'],
                'status':      batch['status'],
                'doubleSharing': 0,
                'clientNames': [],
                'createdAt':   now,
                'updatedAt':   now,
            })

# ── Write to Firestore ────────────────────────────────────────────────────────
print(f"Importing {len(records)} records into hotel_stays...")

col = db.collection('hotel_stays')
batch_size = 400
total = 0

for i in range(0, len(records), batch_size):
    chunk = records[i:i+batch_size]
    batch = db.batch()
    for rec in chunk:
        ref = col.document()
        batch.set(ref, rec)
    batch.commit()
    total += len(chunk)
    print(f"  ✅ Written {total}/{len(records)}")

print(f"\n🏔  Done! {total} stay records imported.")
print(f"   Places: {list(DATA.keys())}")
